import{_ as t,o as n,c as r,ae as a}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Feature Specification: Code Review and Governance Process","description":"","frontmatter":{},"headers":[],"relativePath":"specs/022-code-review-and-governance-process/spec.md","filePath":"specs/022-code-review-and-governance-process/spec.md"}'),i={name:"specs/022-code-review-and-governance-process/spec.md"};function o(s,e,l,c,g,d){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="feature-specification-code-review-and-governance-process" tabindex="-1">Feature Specification: Code Review and Governance Process <a class="header-anchor" href="#feature-specification-code-review-and-governance-process" aria-label="Permalink to &quot;Feature Specification: Code Review and Governance Process&quot;">​</a></h1><p><strong>Feature Branch</strong>: <code>022-code-review-and-governance-process</code><strong>Created</strong>: 2026-02-27 <strong>Status</strong>: Draft <strong>Dependencies</strong>: 021-continuous-integration-and-quality-gates</p><h2 id="user-scenarios-testing-mandatory" tabindex="-1">User Scenarios &amp; Testing <em>(mandatory)</em> <a class="header-anchor" href="#user-scenarios-testing-mandatory" aria-label="Permalink to &quot;User Scenarios &amp; Testing *(mandatory)*&quot;">​</a></h2><h3 id="user-story-1-ensure-every-pr-is-reviewed-before-merge-priority-p1" tabindex="-1">User Story 1 - Ensure Every PR Is Reviewed Before Merge (Priority: P1) <a class="header-anchor" href="#user-story-1-ensure-every-pr-is-reviewed-before-merge-priority-p1" aria-label="Permalink to &quot;User Story 1 - Ensure Every PR Is Reviewed Before Merge (Priority: P1)&quot;">​</a></h3><p>As a project maintainer, I am assured that no pull request reaches main without passing both automated review gates and an agent review so that code quality and constitution compliance are enforced consistently.</p><p><strong>Why this priority</strong>: The constitution requires every PR to be reviewed by another agent and pass GCA/CodeRabbit gates. This is the primary governance enforcement surface.</p><p><strong>Independent Test</strong>: Open a PR, verify that merge is blocked until GCA and CodeRabbit gates pass and an agent reviewer approves. Attempt merge without approval and confirm it is rejected.</p><p><strong>Acceptance Scenarios</strong>:</p><ol><li><strong>Given</strong> a new pull request, <strong>When</strong> it is opened, <strong>Then</strong> GCA and CodeRabbit automated reviews are triggered within 5 minutes.</li><li><strong>Given</strong> a PR with all CI gates passing but no agent review, <strong>When</strong> the author attempts to merge, <strong>Then</strong> the merge is blocked with a message indicating the missing review requirement.</li><li><strong>Given</strong> a PR with all CI gates passing and an agent approval, <strong>When</strong> the author merges, <strong>Then</strong> the merge succeeds and the PR is recorded in the governance log.</li></ol><hr><h3 id="user-story-2-validate-constitution-compliance-during-review-priority-p1" tabindex="-1">User Story 2 - Validate Constitution Compliance During Review (Priority: P1) <a class="header-anchor" href="#user-story-2-validate-constitution-compliance-during-review-priority-p1" aria-label="Permalink to &quot;User Story 2 - Validate Constitution Compliance During Review (Priority: P1)&quot;">​</a></h3><p>As a code reviewer (human or agent), I have a checklist enforced by tooling that covers all constitution review requirements so that nothing is missed.</p><p><strong>Why this priority</strong>: Manual checklists drift. Automated enforcement ensures the constitution review checklist is applied to every PR without exception.</p><p><strong>Independent Test</strong>: Open a PR that violates a constitution requirement (e.g., missing tests for new code), run the compliance check, and confirm the violation is flagged with a reference to the relevant constitution section.</p><p><strong>Acceptance Scenarios</strong>:</p><ol><li><strong>Given</strong> a PR that adds code without corresponding tests, <strong>When</strong> the constitution compliance check runs, <strong>Then</strong> it flags the violation referencing the Testing Requirements section of the constitution.</li><li><strong>Given</strong> a PR that introduces a file exceeding 500 lines, <strong>When</strong> the compliance check runs, <strong>Then</strong> it flags the file size violation referencing the Team Conventions section.</li><li><strong>Given</strong> a PR that passes all compliance checks, <strong>When</strong> the review summary is generated, <strong>Then</strong> it includes a signed-off compliance attestation.</li></ol><hr><h3 id="user-story-3-self-merge-after-all-gates-pass-priority-p2" tabindex="-1">User Story 3 - Self-Merge After All Gates Pass (Priority: P2) <a class="header-anchor" href="#user-story-3-self-merge-after-all-gates-pass-priority-p2" aria-label="Permalink to &quot;User Story 3 - Self-Merge After All Gates Pass (Priority: P2)&quot;">​</a></h3><p>As a developer, I can self-merge my PR after all required gates and reviews have passed so that I am not blocked by scheduling delays while still maintaining full governance.</p><p><strong>Why this priority</strong>: The constitution allows self-merge after all gates pass. This enables velocity without compromising quality.</p><p><strong>Independent Test</strong>: Open a PR, obtain agent approval, confirm all gates pass, self-merge, and verify the governance log records the self-merge with full gate attestation.</p><p><strong>Acceptance Scenarios</strong>:</p><ol><li><strong>Given</strong> a PR with all gates passing and agent approval, <strong>When</strong> the author self-merges, <strong>Then</strong> the merge succeeds and the governance log records the merge as self-merged with full attestation.</li><li><strong>Given</strong> a PR where GCA was rate-limited and did not complete, <strong>When</strong> the author attempts self-merge, <strong>Then</strong> the merge is blocked until GCA re-review is requested and completes.</li></ol><hr><h3 id="user-story-4-document-exceptions-with-adrs-priority-p2" tabindex="-1">User Story 4 - Document Exceptions with ADRs (Priority: P2) <a class="header-anchor" href="#user-story-4-document-exceptions-with-adrs-priority-p2" aria-label="Permalink to &quot;User Story 4 - Document Exceptions with ADRs (Priority: P2)&quot;">​</a></h3><p>As a developer requesting an exception to a constitution rule, I must create an ADR and obtain 3 approvals so that exceptions are traceable and time-bounded.</p><p><strong>Why this priority</strong>: The constitution requires documented exceptions with approvals and sunset dates. This prevents governance erosion.</p><p><strong>Independent Test</strong>: Open a PR that violates a constitution rule with an accompanying ADR, verify the system detects the violation, links to the ADR, and requires 3 approvals before allowing merge.</p><p><strong>Acceptance Scenarios</strong>:</p><ol><li><strong>Given</strong> a PR that violates a constitution rule, <strong>When</strong> an ADR is linked that documents the exception with a sunset date, <strong>Then</strong> the compliance check accepts the exception contingent on 3 approvals.</li><li><strong>Given</strong> an exception ADR without a sunset date, <strong>When</strong> the compliance check runs, <strong>Then</strong> it rejects the exception and requires either a sunset date or an explicit permanence justification.</li></ol><hr><h3 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h3><ul><li>What happens when GCA or CodeRabbit is down or rate-limited? The system must block merge, notify the author, and automatically retry when the service recovers.</li><li>How does the system handle conflicting review feedback from GCA and an agent reviewer? Both must be resolved -- the stricter finding takes precedence.</li><li>What happens when a constitution amendment changes review requirements mid-PR? The PR must be re-evaluated against the updated constitution before merge.</li></ul><h2 id="requirements-mandatory" tabindex="-1">Requirements <em>(mandatory)</em> <a class="header-anchor" href="#requirements-mandatory" aria-label="Permalink to &quot;Requirements *(mandatory)*&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><ul><li><strong>FR-001</strong>: Every PR MUST be blocked from merge until at least one agent reviewer has approved it.</li><li><strong>FR-002</strong>: GCA and CodeRabbit automated reviews MUST be configured as required status checks that block merge on failure or absence.</li><li><strong>FR-003</strong>: If an automated review tool is rate-limited or unavailable, the system MUST block merge and automatically request re-review when the tool recovers.</li><li><strong>FR-004</strong>: Self-merge MUST be permitted only when all CI quality gates (spec 021) pass AND all required reviews are approved.</li><li><strong>FR-005</strong>: A constitution compliance checker MUST validate each PR against the full code review checklist defined in the constitution: correctness, tests, docs, types, error handling, performance, security, anti-patterns, library preference, backward-compat avoidance, and regression risk.</li><li><strong>FR-006</strong>: The compliance checker MUST reference the specific constitution section for each finding.</li><li><strong>FR-007</strong>: Constitution exceptions MUST require a linked ADR with a sunset date (or explicit permanence justification) and 3 approvals before the exception is accepted.</li><li><strong>FR-008</strong>: Every merge MUST be recorded in a governance log with: PR number, author, reviewers, gate results, compliance attestation, exception ADRs (if any), and timestamp.</li><li><strong>FR-009</strong>: The governance log MUST be version-controlled and append-only within the repository.</li><li><strong>FR-010</strong>: Constitution amendments that affect review requirements MUST trigger re-evaluation of open PRs.</li></ul><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><ul><li><strong>NFR-001</strong>: Automated review triggers MUST fire within 5 minutes of PR creation or update.</li><li><strong>NFR-002</strong>: The compliance checker MUST complete within 2 minutes for a typical PR.</li><li><strong>NFR-003</strong>: The governance log MUST be queryable for audit purposes (e.g., &quot;show all self-merges in the last 30 days&quot; or &quot;show all exception ADRs&quot;).</li><li><strong>NFR-004</strong>: Review process configuration MUST be version-controlled alongside the codebase.</li></ul><h3 id="key-entities" tabindex="-1">Key Entities <a class="header-anchor" href="#key-entities" aria-label="Permalink to &quot;Key Entities&quot;">​</a></h3><ul><li><strong>Pull Request Review</strong>: The aggregate review state of a PR including automated gate results, agent reviews, and compliance attestation.</li><li><strong>Compliance Attestation</strong>: A structured record confirming that a PR has been validated against every item in the constitution review checklist.</li><li><strong>Governance Log Entry</strong>: An append-only record of a merge event with full provenance (author, reviewers, gates, exceptions).</li><li><strong>Exception ADR</strong>: An architectural decision record documenting a deviation from the constitution with justification, approvals, and sunset date.</li><li><strong>Review Gate</strong>: A required status check (GCA, CodeRabbit, agent approval) that must pass before merge is permitted.</li></ul><h2 id="success-criteria-mandatory" tabindex="-1">Success Criteria <em>(mandatory)</em> <a class="header-anchor" href="#success-criteria-mandatory" aria-label="Permalink to &quot;Success Criteria *(mandatory)*&quot;">​</a></h2><h3 id="measurable-outcomes" tabindex="-1">Measurable Outcomes <a class="header-anchor" href="#measurable-outcomes" aria-label="Permalink to &quot;Measurable Outcomes&quot;">​</a></h3><ul><li><strong>SC-001</strong>: 100% of merged PRs have at least one agent review approval and passing GCA/CodeRabbit gates in the governance log.</li><li><strong>SC-002</strong>: 100% of constitution exceptions on main are backed by an ADR with 3 approvals and a sunset date or permanence justification.</li><li><strong>SC-003</strong>: Zero PRs are merged while any required review gate is in a rate-limited, unavailable, or incomplete state.</li><li><strong>SC-004</strong>: The compliance checker catches 100% of file-size violations (&gt;500 lines) and missing-test violations in validation runs.</li><li><strong>SC-005</strong>: Governance log entries exist for every merge to main with complete provenance fields.</li></ul><h2 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h2><ul><li>GCA and CodeRabbit are available as GitHub integrations and can be configured as required status checks.</li><li>The CI quality gates from spec 021 are operational and produce structured pass/fail results consumable by the review process.</li><li>Agent reviewers are available (other agents in the project or automated review agents) to provide approvals.</li><li>The constitution is the authoritative source for review checklist items and is version-controlled at <code>docs/reference/constitution.md</code>.</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Migrated from kitty-specs. Tracked in AgilePlus.</p>',47)])])}const p=t(i,[["render",o]]);export{u as __pageData,p as default};
